import{_ as o,o as l,c as n,a5 as r}from"./chunks/framework.Cooo9kuv.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"882-批量图片二维码识别工具","日期":"2026-04-14T00:00:00.000Z","修改日期":"2026-04-14T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["图片批处理"],"标签":["opencv","pyzbar","tkinter","二维码提取","二维码识别","图片扫描","批量处理","批量操作工具","文件删除","文件剪切"]},"headers":[],"relativePath":"md/图片批处理/882-批量图片二维码识别工具.md","filePath":"md/图片批处理/882-批量图片二维码识别工具.md"}'),s={name:"md/图片批处理/882-批量图片二维码识别工具.md"};function i(a,t,g,p,e,c){return l(),n("div",null,[...t[0]||(t[0]=[r('<p>图片二维码批量检测与处理软件，快速扫描指定文件夹中的图片文件，自动识别其中的二维码内容，并根据用户需求执行相应的批量操作。</p><p>软件核心功能包括：</p><ul><li><strong>批量扫描图片文件</strong>：支持扫描指定文件夹下的所有图片文件，可选择是否包含子文件夹</li><li><strong>二维码智能识别</strong>：自动检测图片中的二维码内容，支持多种二维码识别引擎</li><li><strong>批量文件操作</strong>：支持对包含二维码的图片进行剪切、删除或仅识别操作</li><li><strong>识别结果导出</strong>：将二维码识别结果导出为CSV格式文件，方便后续处理</li></ul><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260212202050177089885032200.png" alt=""></p><h3 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h3><ul><li><strong>多种二维码识别引擎支持</strong>：无需联网</li><li><strong>灵活的批量操作模式</strong>：提供剪切、删除、识别三种操作模式，满足不同场景需求</li><li><strong>智能文件名处理</strong>：剪切操作时自动检测重名文件，通过添加时间戳避免覆盖</li><li><strong>多格式图片支持</strong>：支持8位RGB、灰度图、16位深度图片、RGBA多种格式图片的读取和处理</li><li><strong>子文件夹可选扫描</strong>：用户可选择是否扫描子文件夹中的图片文件</li><li><strong>结果超链接导出</strong>：导出的CSV文件包含图片超链接，点击可直接打开对应图片</li></ul><h3 id="基本使用流程" tabindex="-1">基本使用流程 <a class="header-anchor" href="#基本使用流程" aria-label="Permalink to &quot;基本使用流程&quot;">​</a></h3><ol><li><strong>选择扫描路径</strong>：点击”选择文件夹”按钮，选择包含待处理图片的文件夹</li><li><strong>选择操作模式</strong>：在操作模式下拉框中选择需要的操作类型： <ul><li>剪切：将包含二维码的图片移动到指定文件夹</li><li>删除：直接删除包含二维码的图片</li><li>识别：仅识别二维码内容，不进行文件操作</li></ul></li><li><strong>设置输出路径</strong>：如选择剪切或识别模式，需设置输出路径用于存放处理后的文件或结果</li><li><strong>开始处理</strong>：点击”开始”按钮启动批量处理任务</li><li><strong>监控进度</strong>：通过进度条和日志窗口实时查看处理进度和结果</li></ol><h3 id="操作模式详解" tabindex="-1">操作模式详解 <a class="header-anchor" href="#操作模式详解" aria-label="Permalink to &quot;操作模式详解&quot;">​</a></h3><p><strong>剪切模式</strong>：</p><ul><li>将包含二维码的图片移动到输出路径</li><li>如目标位置存在同名文件，自动添加时间戳重命名</li><li>同时生成qrcode.csv文件记录识别结果</li></ul><p><strong>删除模式</strong>：</p><ul><li>直接删除包含二维码的图片文件</li><li>不生成识别结果文件</li><li>操作不可逆，请谨慎使用</li></ul><p><strong>识别模式</strong>：</p><ul><li>仅识别二维码内容，不进行文件操作</li><li>生成qrcode.csv文件记录识别结果</li></ul><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260212203048177089944897248.png" alt=""></p><ul><li>适合仅需获取二维码信息的场景</li></ul><h3 id="使用场景示例" tabindex="-1">使用场景示例 <a class="header-anchor" href="#使用场景示例" aria-label="Permalink to &quot;使用场景示例&quot;">​</a></h3><p><strong>场景一：整理电商商品图片</strong></p><p><strong>需求</strong>：从大量商品图片中筛选出包含二维码的图片，并移动到单独文件夹</p><p><strong>操作步骤</strong>：</p><ol><li>选择包含所有商品图片的文件夹作为扫描路径</li><li>操作模式选择”剪切”</li><li>选择一个空文件夹作为输出路径</li><li>勾选”包含子文件夹”（如图片分散在多个子文件夹）</li><li>点击”开始”按钮</li><li>等待处理完成，所有包含二维码的图片将自动移动到输出文件夹</li><li>打开输出文件夹中的qrcode.csv查看识别结果</li></ol><p><strong>预期结果</strong>：所有包含二维码的图片被移动到指定文件夹，CSV文件记录了每张图片的二维码内容和超链接</p><p><strong>场景二：清理无二维码图片</strong></p><p><strong>需求</strong>：删除一批图片中不包含二维码的图片，仅保留有二维码的图片</p><p><strong>操作步骤</strong>：</p><ol><li>选择待清理的图片文件夹</li><li>操作模式选择”识别”（先识别确认）</li><li>设置输出路径</li><li>点击”开始”查看识别结果</li><li>确认无误后，操作模式改为”删除”</li><li>点击”开始”执行删除操作</li></ol><p><strong>预期结果</strong>：所有包含二维码的图片被删除，仅保留不包含二维码的图片</p><p><strong>注意</strong>：删除操作不可逆，建议先使用识别模式确认结果</p><p><strong>场景三：批量提取二维码信息</strong></p><p><strong>需求</strong>：从大量宣传图片中提取所有二维码内容，用于数据分析</p><p><strong>操作步骤</strong>：</p><ol><li>选择包含宣传图片的文件夹</li><li>操作模式选择”识别”</li><li>设置输出路径用于存放结果文件</li><li>勾选”包含子文件夹”扫描所有子文件夹</li><li>点击”开始”按钮</li><li>处理完成后，打开输出路径下的qrcode.csv文件</li></ol><p><strong>预期结果</strong>：CSV文件包含所有识别到的二维码内容，第一列为图片超链接（可直接点击打开），后续列为二维码内容</p><h3 id="程序截图" tabindex="-1">程序截图 <a class="header-anchor" href="#程序截图" aria-label="Permalink to &quot;程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260212202050177089885032200.png" alt=""></p><p><strong>csv文件效果展示，A列的文件名称为超链接格式，可以查看图片</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260212203252177089957267147.png" alt=""></p><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li><strong>删除模式不可逆</strong>：使用删除模式前请务必确认操作，建议先用识别模式测试</li><li><strong>备份重要数据</strong>：处理前建议备份重要图片文件，避免意外数据丢失</li><li><strong>路径选择</strong>：确保扫描路径和输出路径有足够的磁盘空间</li><li><strong>文件权限</strong>：确保程序有足够的权限访问和操作目标文件夹</li><li><strong>大文件处理</strong>：处理大量文件时可能需要较长时间，请耐心等待</li><li><strong>子文件夹扫描</strong>：勾选”包含子文件夹”会显著增加处理时间，根据实际需求选择</li></ul><h3 id="常见问题解答" tabindex="-1">常见问题解答 <a class="header-anchor" href="#常见问题解答" aria-label="Permalink to &quot;常见问题解答&quot;">​</a></h3><p><strong>Q: 二维码识别率不高怎么办？</strong></p><p>A: 识别率低，可能是图片质量问题，建议提高图片清晰度或调整二维码大小。</p><p><strong>Q: 剪切操作时提示文件已存在怎么办？</strong></p><p>A: 程序会自动处理重名文件，通过添加时间戳（格式：_年月日时分秒微秒）来避免覆盖。如仍出现问题，请检查目标文件夹的写入权限。</p><p><strong>Q: 处理大量文件时程序卡死怎么办？</strong></p><p>A: 程序支持暂停和停止功能，如遇到卡死可点击”停止”按钮终止任务。建议分批处理大量文件，每次处理数量不超过1000张。</p><p><strong>Q: CSV文件中的超链接无法打开怎么办？</strong></p><p>A: 确保使用Excel打开CSV文件，超链接格式为<code>=HYPERLINK(&quot;file:///完整路径&quot;,&quot;显示名称&quot;)</code>。如无法打开，检查图片路径是否正确，或尝试手动复制路径到文件资源管理器。</p><p><strong>Q: 支持哪些图片格式？</strong></p><p>A: 包括但不限于JPG、PNG、BMP、TIFF。程序会自动将图片转换为8位RGB格式进行处理。</p><p><strong>Q: 能否识别多个二维码？</strong></p><p>A: 可以。程序能够识别单张图片中的多个二维码，识别结果会全部记录在CSV文件中，每个二维码占一列。</p><h3 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h3><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h3 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h3><p><strong>解压后，看到如下文件，双击快捷方式使用即可（快捷方式上有个箭头），快捷方式可以放到任意位置。</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260212203424177089966417540.png" alt=""></p><p><strong>如下所示，文件夹及文件夹内所有内容都不要删除，如果突然无法使用了大概率是杀毒软件给误杀了，请重新解压使用即可</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260212203450177089969069975.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2479.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2479.html</a></p>',65)])])}const u=o(s,[["render",i]]);export{d as __pageData,u as default};
